import json, pathlib, subprocess, tempfile, textwrap; repo = pathlib.Path.cwd();

def write_project(name, source):
    root = pathlib.Path(tempfile.mkdtemp(prefix=f'fozzylang-{name}-'))
    (root / 'src').mkdir(parents=True, exist_ok=True)
    (root / 'fozzy.toml').write_text(textwrap.dedent(f'''\
        [package]
        name="{name}"
        version="0.1.0"

        [[target.bin]]
        name="{name}"
        path="src/main.fzy"
    '''))
    (root / 'src/main.fzy').write_text(textwrap.dedent(source))
    return root

def verify(name, source, expect_rc):
    root = write_project(name, source)
    proc = subprocess.run(['cargo', 'run', '-q', '-p', 'fz', '--', 'verify', str(root), '--json'], cwd=str(repo), capture_output=True, text=True)
    payload = json.loads(proc.stdout.strip())
    assert proc.returncode == expect_rc, (name, proc.returncode, payload, proc.stderr)
    return payload

def messages(payload):
    return [item['message'] for item in payload['items']]

def find_message(payload, needle):
    return next(item for item in payload['items'] if needle in item['message'])

if_expr_move = verify('if_expr_move', '''
    fn main() -> i32 {
        let p = alloc(32)
        let q = if true { p } else { alloc(64) }
        free(p)
        free(q)
        return 0
    }
''', 1)
if_expr_diag = find_message(if_expr_move, 'uses conditionally consumed value `p` after path-sensitive ownership merge')
assert 'ownership transfer semantics' in (if_expr_diag.get('help') or ''), if_expr_diag

match_expr_move = verify('match_expr_move', '''
    fn main() -> i32 {
        let p = alloc(32)
        let q = match true {
            true => p,
            _ => alloc(64),
        }
        free(p)
        free(q)
        return 0
    }
''', 1)
match_expr_diag = find_message(match_expr_move, 'uses conditionally consumed value `p` after path-sensitive ownership merge')
assert 'ownership transfer semantics' in (match_expr_diag.get('help') or ''), match_expr_diag

grouped_move = verify('grouped_move', '''
    fn main() -> i32 {
        let p = alloc(32)
        let q = (p)
        free(p)
        free(q)
        return 0
    }
''', 1)
grouped_move_diag = find_message(grouped_move, 'uses moved value `p` after move/consume')
assert 'ownership transfer semantics' in (grouped_move_diag.get('help') or ''), grouped_move_diag

return_if_expr_leak = verify('return_if_expr_leak', '''
    fn produce(flag: i32) -> *mut u8 {
        let p = alloc(32)
        return if flag == 0 { p } else { alloc(64) }
    }
    fn main() -> i32 {
        let p = produce(0)
        free(p)
        return 0
    }
''', 1)
assert any('function `produce` leaks allocation id=1 owned by `p`' in message for message in messages(return_if_expr_leak)), return_if_expr_leak

return_match_expr_leak = verify('return_match_expr_leak', '''
    fn produce(flag: i32) -> *mut u8 {
        let p = alloc(32)
        return match flag {
            0 => p,
            _ => alloc(64),
        }
    }
    fn main() -> i32 {
        let p = produce(0)
        free(p)
        return 0
    }
''', 1)
assert any('function `produce` leaks allocation id=1 owned by `p`' in message for message in messages(return_match_expr_leak)), return_match_expr_leak

return_if_expr_pass = verify('return_if_expr_pass', '''
    fn produce(flag: i32) -> *mut u8 {
        let p = alloc(32)
        return if flag == 0 { p } else { (p) }
    }
    fn main() -> i32 {
        let p = produce(0)
        free(p)
        return 0
    }
''', 0)
assert return_if_expr_pass['errors'] == 0, return_if_expr_pass

return_match_expr_pass = verify('return_match_expr_pass', '''
    fn produce(flag: i32) -> *mut u8 {
        let p = alloc(32)
        return match flag {
            0 => p,
            _ => (p),
        }
    }
    fn main() -> i32 {
        let p = produce(0)
        free(p)
        return 0
    }
''', 0)
assert return_match_expr_pass['errors'] == 0, return_match_expr_pass

if_expr_pass = verify('if_expr_pass', '''
    fn main() -> i32 {
        let q = if true { alloc(32) } else { alloc(64) }
        free(q)
        return 0
    }
''', 0)
assert if_expr_pass['errors'] == 0, if_expr_pass
assert not any('conditionally consumed value' in message for message in messages(if_expr_pass)), if_expr_pass

print('compiler-memory-expression-moves-ok')

